    // The Video window, after the reference's: the picture of the video clip under the play head,
    // playing along while the transport plays. The clip plays the movie's sound, so the picture is silent.
    class VideoWindow final : public juce::DocumentWindow
    {
    public:
        VideoWindow() : DocumentWindow ("Video", juce::Colours::black, DocumentWindow::closeButton)
        {
            setUsingNativeTitleBar (true); setResizable (true, false);
            picture.setName ("Video picture");
            setContentNonOwned (&picture, false);
            centreWithSize (480, 270);
        }
        void closeButtonPressed() override { setVisible (false); }
        void follow (const std::optional<Session::VideoFrame>& frame, bool playing)
        {
            if (! frame)
            {
                if (shown != juce::File()) { picture.closeVideo(); shown = juce::File(); }
                return;
            }
            if (frame->movie != shown)
            {
                if (picture.load (frame->movie).failed()) return;
                picture.setAudioVolume (0); shown = frame->movie;
            }
            const auto at = picture.getPlayPosition();
            if (playing)
            {
                // Played along, and moved back into step when it drifts more than 0.1 s.
                if (! picture.isPlaying()) { picture.setPlayPosition (frame->seconds); picture.play(); }
                else if (std::abs (at - frame->seconds) > 0.1) picture.setPlayPosition (frame->seconds);
            }
            else
            {
                if (picture.isPlaying()) picture.stop();
                if (std::abs (at - frame->seconds) > 0.001) picture.setPlayPosition (frame->seconds);
            }
        }
        juce::File shownMovie() const { return shown; }
        double position() const { return picture.getPlayPosition(); }
    private:
        juce::VideoComponent picture { false };
        juce::File shown;
    };
    std::unique_ptr<VideoWindow> videoWindow;
    // Pictures for video clips in the Arrangement, made on a thread of their own and kept: a clip
    // draws the pictures it has, and asks for those it lacks, which repaint the clips once made.
    class VideoThumbnails final : private juce::Thread
    {
    public:
        explicit VideoThumbnails (std::function<void()> made) : Thread ("Video pictures"), onMade (std::move (made)) {}
        ~VideoThumbnails() override { stopThread (4000); }
        juce::Image get (const juce::File& movie, double seconds, int height)
        {
            const auto key = movie.getFullPathName() + "|" + juce::String (seconds, 2) + "|" + juce::String (height);
            {
                const juce::ScopedLock lock (mutex);
                if (const auto found = made.find (key); found != made.end()) return found->second;
                if (std::none_of (wanted.begin(), wanted.end(), [&] (const auto& w) { return w.key == key; })) wanted.push_back ({ key, movie, seconds, height });
            }
            if (! isThreadRunning()) startThread();
            notify();
            return {};
        }
    private:
        struct Request { juce::String key; juce::File movie; double seconds = 0; int height = 0; };
        void run() override
        {
            while (! threadShouldExit())
            {
                std::optional<Request> next;
                { const juce::ScopedLock lock (mutex); if (! wanted.empty()) { next = wanted.front(); wanted.pop_front(); } }
                if (! next) { wait (500); continue; }
                auto image = video::frameImage (next->movie, next->seconds, next->height);
                {
                    const juce::ScopedLock lock (mutex);
                    if (made.size() >= 2048) made.clear();
                    made[next->key] = image;
                }
                juce::MessageManager::callAsync (onMade);
            }
        }
        std::function<void()> onMade;
        juce::CriticalSection mutex;
        std::map<juce::String, juce::Image> made;
        std::deque<Request> wanted;
    };
    std::unique_ptr<VideoThumbnails> videoThumbnails;
