            const auto tracksBefore = state.tracks.size();
            check (session.addMidiTrack ("Group").wasOk(), "a track of clips"); refresh();
            int t = -1;
            for (int i = 0; i < (int) state.tracks.size(); ++i) if (state.tracks[(size_t) i].name == "Group") t = i;
